pub type BoundedCounter = {
  value: Int;
} invariant: this.value >= 0 && this.value <= 100;

impl BoundedCounter {
  fn increment(self: &mut Self)
    requires: self.value < 100;
    ensures: self.value == self@pre.value + 1;
  {
    self.value = self.value + 1;
  }
}

fn main() -> Int {
  var c = BoundedCounter{ value: 50 };
  c.increment();
  return c.value;
}
